mapper.select:
SELECT ci.id, ci.serial_number AS serialNumber, ci.status, ci.issue_date AS issueDate, ci.expire_date AS expireDate, ci.validity_label AS validityLabel, ci.blockchain_hash AS blockchainHash, ci.template_id AS templateId, ct.title AS templateTitle, ct.level_label AS levelLabel, ct.category, ct.issue_org AS issueOrg, ct.validity_months AS validityMonths, ct.description, ct.privilege_text AS privilegeText, ci.user_id AS userId, u.name AS userName, u.employee_no AS employeeNo, u.avatar_url AS avatarUrl, d.name AS department FROM certificate_issue ci JOIN certificate_template ct ON ct.id = ci.template_id JOIN sys_user u ON u.id = ci.user_id LEFT JOIN department d ON d.id = u.department_id WHERE ci.deleted_at IS NULL AND ci.status = #{status}
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR ci.serial_number LIKE CONCAT('%', #{keyword}, '%') OR ct.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY ci.id DESC
